ariable","target":"method"},"defaultValue":"dual-place composition","id":"method","label":"Visual method","type":"text"},{"binding":{"mode":"variable","target":"structure"},"defaultValue":"the center seam is a believable spatial transition, not a graphic divider","id":"structure","label":"Composition rule","type":"textarea"},{"binding":{"mode":"generation","target":"aspectRatio"},"defaultValue":"4:5","id":"aspect-ratio","label":"Format","options":[{"label":"Portrait 4:5","value":"4:5"},{"label":"Tall 9:16","value":"9:16"},{"label":"Square 1:1","value":"1:1"},{"label":"Landscape 3:2","value":"3:2"}],"type":"aspect-ratio"}],"description":"Show two truthful sides of one city meeting in a narrow transition.","generation":{"capability":"image-generation","defaultOperation":"generate","defaultVariationCount":1,"delivery":"webmcp-import","operations":["generate","edit","variation","upscale"],"preferredMimeTypes":["image/png","image/webp"],"provider":"codex"},"id":"two-sided-city-story","layout":{"arrangement":"prompt-left-output-right","mode":"seeded","preserveManualGeometry":true},"outputs":[{"aspectRatio":"4:5","count":1,"id":"primary","kind":"image","label":"Result","layoutHint":"hero","operations":["generate","edit","variation","upscale"],"required":true,"role":"primary"}],"preservation":[{"appliesTo":["method","structure"],"description":"Preserve the defining dual-place composition method and this composition obligation: the center seam is a believable spatial transition, not a graphic divider.","id":"creative-mechanism","label":"Creative mechanism","strength":"must"}],"prompt":{"agentInstructions":"Resolve all visible controls and reference obligations before generation. Produce one candidate by default and return it to the primary output slot.","body":"Show two truthful sides of one city meeting in a narrow transition. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one cle